head.script:

scwin.onpageload = function () {
    var jsnParamData = $p.getParameter("admin_param");
    var initialData = {
        adminId: jsnParamData.email,
        adminName : jsnParamData.name,
        tenant : jsnParamData.tenant,
        company : jsnParamData.company
    };
    dma_managerInfo.setJSON(initialData);
    welcomeText.setValue(dma_managerInfo.get("adminName")+"님, 회원가입을 환영합니다.");

    const origin = window.location.origin;
    const tenantUrl = origin+"/"+"tenant/"+dma_managerInfo.get("tenant")
    tbx_adminUrl.setValue(tenantUrl)
    tenantServiceUrl.setValue(tenantUrl)

    scwin.url = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/unicon_tenant_login_page.xml&tenant="+dma_managerInfo.get("tenant");
    hiddenUrl.setValue(origin + scwin.url)

};

scwin.goToDashboard = function () {
    location.href = scwin.url;
};

scwin.moveToHomeBtn_onclick = function (e) {
    $p.closePopup();
};


scwin.idCopy_onclick = function (e) {
    console.log("복사되었다링고")
    $c.util.copyClipboard(tbx_adminId);
    idCopy.setLabel("복사됨");

};

scwin.urlCopy_onclick = function (e) {
    console.log("복사되었다링고2")
    $c.util.copyClipboard(hiddenUrl);
    urlCopy.setValue("복사됨");
};
